  'Business Law',
  'This course introduces the legal environment of business through the lens of human resources. Students learn the foundations of courts, contracts, agency, torts, business organizations, employment law, labor law, regulation, intellectual property, privacy, ethics, and legal case analysis. The emphasis is practical: spotting legal issues early, documenting decisions responsibly, knowing when to involve counsel, and communicating risk in a professional HR voice.',
  $blawjson${"slug": "business-law", "title": "Business Law", "description": "This course introduces the legal environment of business through the lens of human resources. Students learn the foundations of courts, contracts, agency, torts, business organizations, employment law, labor law, regulation, intellectual property, privacy, ethics, and legal case analysis. The emphasis is practical: spotting legal issues early, documenting decisions responsibly, knowing when to involve counsel, and communicating risk in a professional HR voice.", "topics": [{"id": "251a65d6-8489-43c8-bf63-4ef7c49897a7", "type": "topic", "title": "Legal Systems, Courts, and HR Legal Reasoning", "description": "Students learn how law is made, interpreted, and applied to workplace and business decisions. The goal is legal literacy: recognizing risk, organizing facts, communicating with counsel, and understanding how courts and agencies resolve disputes.", "children": [{"id": "fb8152d4-414d-4ccf-ac30-940da6b2a6ee", "type": "subtopic", "title": "Sources of law", "children": [{"id": "8d67d5b8-9209-4bdc-b554-ee47f52ecdad", "type": "concept", "title": "Constitutions"}, {"id": "4c0b6ca7-7e25-4162-8f5c-053933ad454a", "type": "concept", "title": "Statutes"}, {"id": "f8296bb6-960b-4653-9a3e-db785bd6cf81", "type": "concept", "title": "Regulations"}, {"id": "8ed6a328-b05d-4dfb-9269-aa113d654806", "type": "concept", "title": "Common law"}, {"id": "02cdfa46-4124-4750-b45c-cd67337a75c1", "type": "concept", "title": "Administrative guidance"}], "description": "This subtopic gives students the map of legal authority that governs business and HR decisions."}, {"id": "81991604-68b4-464c-aab6-f312a555edee", "type": "subtopic", "title": "Court systems and jurisdiction", "children": [{"id": "a745b36f-8986-481f-978d-9a2e438a5af9", "type": "concept", "title": "Federal versus state courts"}, {"id": "5b4fa759-2748-40c2-9c3b-018a9358faae", "type": "concept", "title": "Trial and appellate courts"}, {"id": "d3ffb13e-ec8b-4591-97db-7f1ddd31bd6f", "type": "concept", "title": "Jurisdiction"}, {"id": "99af2df0-0fbb-476e-be6c-d3f8f597a409", "type": "concept", "title": "Venue"}, {"id": "40cb3d63-b01a-48a3-a753-326114d2aa11", "type": "concept", "title": "Civil versus criminal matters"}], "description": "Students learn where disputes are heard and why forum, procedure, and remedies matter."}, {"id": "30db72c2-99d6-49fb-a5d1-3cf0d358dfa9", "type": "subtopic", "title": "Legal reasoning for HR professionals", "children": [{"id": "24b9f4e0-e2d4-4944-a128-011889ea1cec", "type": "concept", "title": "Issue-rule-application-conclusion"}, {"id": "8ca1995a-a634-46bc-a116-df9048b086aa", "type": "concept", "title": "Material facts"}, {"id": "39b0e95c-8f7c-429a-a205-edd2817dbbc1", "type": "concept", "title": "Precedent"}, {"id": "e780e771-e89e-4f98-af91-f28fba90538e", "type": "concept", "title": "Risk escalation"}, {"id": "6b60da88-a79a-4db9-9828-3687c0f22c0d", "type": "concept", "title": "Documentation habits"}], "description": "The point is to move from vague concern to structured issue spotting and defensible recommendations."}]}, {"id": "b77d2e22-1f42-454e-91c5-6e49827d5152", "type": "topic", "title": "Contracts: Formation, Performance, Breach, and Remedies", "description": "Contracts are the operating system of business relationships. HR students learn how promises become enforceable, how agreements are interpreted, and how contract design affects employees, vendors, consultants, and executives.", "children": [{"id": "1fd2f556-c864-47f6-ad66-572c5b0af5c6", "type": "subtopic", "title": "Contract formation", "children": [{"id": "82ace9f6-1352-4c99-8deb-b017566fe947", "type": "concept", "title": "Offer"}, {"id": "721435b9-9855-4832-a6f5-cdc7c4bfcdf5", "type": "concept", "title": "Acceptance"}, {"id": "9c86c763-c364-4a3c-bafc-65fecbfb5459", "type": "concept", "title": "Consideration"}, {"id": "d87d72fa-580f-41e4-95af-708f9a140657", "type": "concept", "title": "Capacity"}, {"id": "448d718a-a134-464a-a3a1-1090c46cfa7e", "type": "concept", "title": "Legality"}, {"id": "bc17c314-4c0d-4863-9777-8583fb910795", "type": "concept", "title": "Mutual assent"}], "description": "Students learn the elements that turn negotiation into an enforceable obligation."}, {"id": "bf66aabd-bbda-45cf-a180-eb704eb15212", "type": "subtopic", "title": "Performance and breach", "children": [{"id": "14899b17-ea22-48c8-bfd1-6d3efaddf821", "type": "concept", "title": "Conditions"}, {"id": "9e53e8f5-d861-491c-9f96-60a0be3b1581", "type": "concept", "title": "Material breach"}, {"id": "a35128f1-7f80-4676-b2f9-992a06ff7ea2", "type": "concept", "title": "Substantial performance"}, {"id": "95bc5ad2-44ab-4698-b0d1-60afb92ce699", "type": "concept", "title": "Impossibility"}, {"id": "e8b96ff9-54cf-4772-ab82-1ed8eb2e6afc", "type": "concept", "title": "Good faith"}, {"id": "5b78bc9c-ad97-41dd-b658-c9d1a9d8bc27", "type": "concept", "title": "Mitigation"}], "description": "This subtopic shows how obligations are fulfilled, excused, or violated."}, {"id": "bd28d464-2389-4c1a-b435-1f8a44cc2478", "type": "subtopic", "title": "Remedies and drafting controls", "children": [{"id": "35a1f98d-794e-4670-ad08-04ec1f317cfe", "type": "concept", "title": "Expectation damages"}, {"id": "f09e51c3-adbe-4613-a261-63bd4f62a2b6", "type": "concept", "title": "Specific performance"}, {"id": "9ddaf584-97fd-4c90-a8a6-f25bbfdf4259", "type": "concept", "title": "Liquidated damages"}, {"id": "bc988ceb-7a65-4bb8-8900-54ce18d58c87", "type": "concept", "title": "Limitation of liability"}, {"id": "937cc14b-c0c4-42d9-87f6-0c7a503a00ee", "type": "concept", "title": "Indemnification"}, {"id": "44792c41-b810-4f99-a68c-1d5b04ce0af8", "type": "concept", "title": "Dispute clauses"}], "description": "Students learn how contracts allocate risk before something goes wrong."}]}, {"id": "24b78a98-3160-48d4-907d-019176ebca93", "type": "topic", "title": "Agency Law and Authority in Organizations", "description": "Agency law explains how organizations act through people. For HR, it is essential for understanding hiring authority, supervisor conduct, apparent authority, fiduciary duties, and organizational liability.", "children": [{"id": "67b8c05d-7b9b-4831-9297-6355eb129594", "type": "subtopic", "title": "Creation of agency relationships", "children": [{"id": "44e2ad6a-7004-46ae-964b-6e7d03fa83b9", "type": "concept", "title": "Principal and agent"}, {"id": "de8066eb-320b-4f5f-b00f-090e68b4b6a0", "type": "concept", "title": "Actual authority"}, {"id": "49a6c8a0-2ba4-478f-8f40-e884d7a28927", "type": "concept", "title": "Apparent authority"}, {"id": "89c1f6c4-a560-4a6f-90a2-2a416fbcd1f4", "type": "concept", "title": "Ratification"}, {"id": "f4d172d4-3554-4a18-9554-f8360deba101", "type": "concept", "title": "Independent contractors"}], "description": "Students learn when one person legally acts on behalf of another person or entity."}, {"id": "10092986-e30f-478c-b1d2-9b238a3a715d", "type": "subtopic", "title": "Duties of agents and principals", "children": [{"id": "948fae21-b54a-4499-8f52-0a22e5f1882a", "type": "concept", "title": "Duty of loyalty"}, {"id": "346cd1a0-04c6-4df2-ad57-6d10c282c7de", "type": "concept", "title": "Duty of care"}, {"id": "33536ed1-b3c1-4811-a5fe-2fa0029596d2", "type": "concept", "title": "Conflicts of interest"}, {"id": "9f67f72a-31d0-4fdc-b4ae-136a9196d376", "type": "concept", "title": "Confidentiality"}, {"id": "d6699e88-2bd9-424e-abb1-aa0ac04d9770", "type": "concept", "title": "Indemnification"}], "description": "This subtopic explains loyalty, care, disclosure, and accountability within organizational roles."}, {"id": "39c7bc20-50b8-440b-89ba-b1249c4f59e1", "type": "subtopic", "title": "Employer liability for agents", "children": [{"id": "cb5c5d5b-42f9-45c0-a791-9d9ee844e9f1", "type": "concept", "title": "Respondeat superior"}, {"id": "850d8ce4-73f0-41b6-8a83-dd3c723bcf4e", "type": "concept", "title": "Scope of employment"}, {"id": "46f23d83-f275-446a-9243-726e9a288cf1", "type": "concept", "title": "Frolic and detour"}, {"id": "c8508307-47c0-44ea-9b93-d0e55a0520d9", "type": "concept", "title": "Negligent hiring"}, {"id": "d492a597-57ec-456c-8bfa-c557cb983bba", "type": "concept", "title": "Supervisor conduct"}], "description": "Students learn when organizations are responsible for employee or manager conduct."}]}, {"id": "38a2e06d-b431-4050-bbfe-d419cd1dca85", "type": "topic", "title": "Torts, Negligence, Product Liability, and Workplace Risk", "description": "Tort law teaches students how businesses become liable for harm outside contract. HR students connect tort concepts to workplace safety, defamation, negligent hiring, emotional distress, and risk prevention.", "children": [{"id": "69d38aef-2b62-4e27-85f9-6469fb5a239b", "type": "subtopic", "title": "Negligence and duty of care", "children": [{"id": "91b999a6-0199-41e8-80df-4a7839c7039d", "type": "concept", "title": "Duty"}, {"id": "5320bd9c-507c-4e29-968d-d9ff4ace9007", "type": "concept", "title": "Breach"}, {"id": "177ddaa7-501a-4bc0-8c8b-3fd8489a70a0", "type": "concept", "title": "Causation"}, {"id": "2158c689-ce62-4b1f-abcf-31ac7aa60899", "type": "concept", "title": "Damages"}, {"id": "cb6f312c-9a3e-4a76-857c-b9e8e211e878", "type": "concept", "title": "Foreseeability"}, {"id": "891febd6-230d-43cc-9d4c-4a18e3133343", "type": "concept", "title": "Comparative fault"}], "description": "Students learn the basic framework for civil liability based on unreasonable conduct."}, {"id": "c5046b9d-0d7f-4572-a657-82f7d24e9804", "type": "subtopic", "title": "Intentional and business torts", "children": [{"id": "67acd8f8-ea1f-49ef-9e3b-34a184a3a4fd", "type": "concept", "title": "Defamation"}, {"id": "db1c3140-15f2-4c12-bbce-7ddf24518a5e", "type": "concept", "title": "Fraud"}, {"id": "5ed421fb-9c1c-4fe5-aa63-41eaa0fd45e5", "type": "concept", "title": "Interference with contract"}, {"id": "01ef5517-6d83-41ee-a413-300fd1715375", "type": "concept", "title": "Intentional infliction of emotional distress"}, {"id": "632398e2-14cf-45de-a909-0e92d4aa54c9", "type": "concept", "title": "Invasion of privacy"}], "description": "This subtopic helps students recognize workplace and commercial conduct that creates civil exposure."}, {"id": "bce662c1-880e-48a9-addb-c4dfe5972c44", "type": "subtopic", "title": "Workplace tort risk", "children": [{"id": "b289df7a-783c-4d18-8377-484f7186dd0b", "type": "concept", "title": "Negligent hiring"}, {"id": "e97f9ea1-0123-4d51-8637-775f480972b5", "type": "concept", "title": "Negligent retention"}, {"id": "8086306b-896f-4713-9d88-61eabfec2013", "type": "concept", "title": "Workplace violence"}, {"id": "c5a49801-5f6c-4938-b29b-e529df371269", "type": "concept", "title": "Reference checks"}, {"id": "26505f25-efb0-4f0d-8428-e087d552978d", "type": "concept", "title": "Investigation notes"}, {"id": "1bab4afd-3d96-4037-b1aa-c088787946d8", "type": "concept", "title": "Insurance and risk transfer"}], "description": "Students connect legal doctrine to hiring, supervision, references, investigations, and safety."}]}, {"id": "466618d0-150e-47e3-b01f-ab4f213af8da", "type": "topic", "title": "Business Organizations, Governance, and Fiduciary Duties", "description": "Students learn the legal forms businesses use and how governance structures allocate authority, responsibility, liability, and accountability. HR professionals need this foundation when advising leaders and operating in complex organizations.", "children": [{"id": "64bd624e-3965-472d-88d3-aeb65c68b483", "type": "subtopic", "title": "Entity forms and liability", "children": [{"id": "a34584d9-aee5-4eb7-af10-7eb37e963ca5", "type": "concept", "title": "Sole proprietorships"}, {"id": "5f4e6fd9-54c5-4f63-97a3-911aa746c702", "type": "concept", "title": "Partnerships"}, {"id": "b09953af-d8ad-455f-bfa1-cbbe77ba8083", "type": "concept", "title": "LLCs"}, {"id": "5a8b08b3-e791-44cf-a7ca-494a9d55779c", "type": "concept", "title": "Corporations"}, {"id": "cc26c144-5647-43a4-9c3c-14da2d6683df", "type": "concept", "title": "Limited liability"}, {"id": "82d1b1bb-aedb-46bb-adca-aac2fb25ffb9", "type": "concept", "title": "Piercing the veil"}], "description": "This subtopic compares the main legal structures used by employers and clients."}, {"id": "7aad3467-6b63-4603-9eba-ad8b91f7b925", "type": "subtopic", "title": "Corporate governance", "children": [{"id": "bc50ab69-6666-436b-9b09-7e4caaf6a17d", "type": "concept", "title": "Board authority"}, {"id": "8aef7399-3a90-4725-bb2c-623d677ad4bd", "type": "concept", "title": "Officer roles"}, {"id": "a861469c-5ea1-46c2-ad60-22c53d2089f9", "type": "concept", "title": "Shareholder rights"}, {"id": "d18bc76c-9b1c-4ac4-b543-23d09ebeb93b", "type": "concept", "title": "Corporate records"}, {"id": "e3de1d37-eccc-41b9-9cec-46d6f8885bf7", "type": "concept", "title": "Internal controls"}], "description": "Students learn how directors, officers, shareholders, and managers make and supervise decisions."}, {"id": "b760ebc6-b0a2-4b98-9db2-8a3a59410a60", "type": "subtopic", "title": "Fiduciary duties and ethical governance", "children": [{"id": "43b18b85-40ae-45ab-9054-ace7a8c0ea64", "type": "concept", "title": "Duty of care"}, {"id": "11b983b4-293d-460e-b7f2-5e93025bdf0b", "type": "concept", "title": "Duty of loyalty"}, {"id": "75ae95b7-22ce-4a70-85c6-95a11f8449e2", "type": "concept", "title": "Business judgment rule"}, {"id": "69e33c85-b471-4731-b86d-9fe887159aa1", "type": "concept", "title": "Conflicts of interest"}, {"id": "0cac8ee2-0b7a-4c04-91ba-7b36aae3b3a6", "type": "concept", "title": "Whistleblower channels"}, {"id": "d8de88f0-c75e-4c65-ba3f-e1f04c9f5dc5", "type": "concept", "title": "Board reporting"}], "description": "The goal is to understand legal duties of loyalty and care in business leadership."}]}, {"id": "173a5f02-9306-4aa5-bda3-e33c7ccd23c0", "type": "topic", "title": "Employment Law Foundations for HR", "description": "For a Human Resources degree, employment law needs real depth. Students learn the legal baseline for hiring, classification, pay, leave, accommodation, discipline, discharge, and employee relations.", "children": [{"id": "6535b660-5231-4e46-961d-bf4830f1985b", "type": "subtopic", "title": "Employment relationship and classification", "children": [{"id": "26da515a-28fd-4906-a6ef-fe74393500e7", "type": "concept", "title": "At-will employment"}, {"id": "1551fdf5-309b-483b-b29b-7ea9d8fc60a9", "type": "concept", "title": "Employee versus independent contractor"}, {"id": "441db0fb-de2f-45db-bf6e-f1b090c43f92", "type": "concept", "title": "Exempt versus nonexempt"}, {"id": "92a531a4-bae1-430e-a9ea-e981bb54cf6a", "type": "concept", "title": "Joint employment"}, {"id": "58cd9625-6def-4465-996e-5c16a52c5fa3", "type": "concept", "title": "Interns and trainees"}], "description": "Students learn how legal status affects rights, pay, benefits, taxes, and liability."}, {"id": "165a638a-c53f-4ed3-8140-f56e0c76b3f7", "type": "subtopic", "title": "Equal employment opportunity", "children": [{"id": "fad6e39b-c24b-4b5e-a4ae-9fb4cafe5a22", "type": "concept", "title": "Title VII"}, {"id": "6371df50-d00b-4081-b5ca-9ce9d1cf89c8", "type": "concept", "title": "ADA"}, {"id": "e29f127d-2169-4b17-bb28-413847cc79ed", "type": "concept", "title": "ADEA"}, {"id": "968d2cbf-8ab7-4d83-9aa8-8cb7a52e29d9", "type": "concept", "title": "Pregnancy discrimination"}, {"id": "98bb1166-0161-4bf3-aea3-b5b36e7ed76d", "type": "concept", "title": "Harassment"}, {"id": "68605aa7-20da-401e-b74e-0d607d3ee332", "type": "concept", "title": "Retaliation"}], "description": "This subtopic introduces the legal framework for fair treatment across the employment lifecycle."}, {"id": "b20e7637-c194-43b4-9e80-89b21873dbda", "type": "subtopic", "title": "Workplace standards and separation", "children": [{"id": "ed490cfc-741f-429d-b14c-54dfe3476015", "type": "concept", "title": "FLSA"}, {"id": "c0025a2d-17d5-4764-ab35-e0c0bb61597f", "type": "concept", "title": "FMLA"}, {"id": "79af7856-b0b8-4de0-998c-025c3810e322", "type": "concept", "title": "OSHA"}, {"id": "7ae901eb-8285-42e8-bb56-0847e687a074", "type": "concept", "title": "Wrongful discharge"}, {"id": "9ae335ad-1aa7-437d-8607-b979d80ca69c", "type": "concept", "title": "Progressive discipline"}, {"id": "15a6f32f-1d7d-4b0e-bd22-fc42d06fd316", "type": "concept", "title": "Severance and releases"}], "description": "Students learn core rules that govern pay, leave, safety, discipline, and termination."}]}, {"id": "236540f1-056a-4e9c-9124-922934c0e899", "type": "topic", "title": "Labor Law, Employee Voice, and Collective Activity", "description": "A world-class HR business law course should not stop at individual employment rights. Students learn how labor law protects collective activity, union organizing, bargaining, and protected employee voice.", "children": [{"id": "88a2d8a3-524f-496b-85e2-1fbb7f0c238b", "type": "subtopic", "title": "National Labor Relations Act basics", "children": [{"id": "834c7930-7271-4061-9efd-b0fb62ac7d72", "type": "concept", "title": "Protected concerted activity"}, {"id": "43c4e0b0-8e42-49b2-9730-c53f3d30c5e2", "type": "concept", "title": "Section 7 rights"}, {"id": "d5998190-9457-4cb2-b9f0-879887fe92cb", "type": "concept", "title": "Unfair labor practices"}, {"id": "1714ae14-dff4-4bee-9824-45e257b7c607", "type": "concept", "title": "NLRB process"}, {"id": "9063859a-e0a1-4044-81fa-773f8a8f077c", "type": "concept", "title": "Manager do's and don'ts"}], "description": "Students learn the federal framework for private-sector union and nonunion employee rights."}, {"id": "d3a35bfa-f9c3-495d-9d5a-73a1b528aea8", "type": "subtopic", "title": "Organizing and bargaining", "children": [{"id": "42c32db2-208d-463f-a0b5-b6af7fd8cc03", "type": "concept", "title": "Authorization cards"}, {"id": "aa238a64-a36a-4592-adb4-0ba22b966b78", "type": "concept", "title": "Representation elections"}, {"id": "01d19e75-4070-4a9f-9859-4fc5cad9b08b", "type": "concept", "title": "Duty to bargain"}, {"id": "be5e9ef5-f7f4-413f-a366-ae1873bb6aff", "type": "concept", "title": "Management rights"}, {"id": "218cf6e0-9beb-4ca1-b6eb-93b879332bc1", "type": "concept", "title": "Collective bargaining agreements"}], "description": "This subtopic introduces how representation, negotiation, and contracts shape workplace governance."}, {"id": "64a4ac7e-a5a7-4f0b-85e3-622ff3486bea", "type": "subtopic", "title": "Employee voice beyond unions", "children": [{"id": "44fd4f82-2cc0-4eca-a1d2-59f2ac7c8888", "type": "concept", "title": "No-retaliation rules"}, {"id": "61904ba5-50ea-45ba-afde-32d71e2334c2", "type": "concept", "title": "Handbook policies"}, {"id": "63a7c271-3abc-4e30-8c61-bf66390fbd7d", "type": "concept", "title": "Confidentiality limits"}, {"id": "a64437ed-e013-4a93-bf2a-9ab95c12e33b", "type": "concept", "title": "Whistleblowing"}, {"id": "cad1f33c-25d0-4d04-9fcb-6e7b123c4aae", "type": "concept", "title": "Speak-up culture"}], "description": "Students understand legal risk in policies that affect complaints, social media, and workplace organizing."}]}, {"id": "84a4f2df-1543-41e3-821b-2684acab0707", "type": "topic", "title": "Regulation, Compliance Systems, and Risk Management", "description": "Regulation is not only a list of rules; it is a management system. Students learn how businesses build controls, training, audits, documentation, and reporting pathways that prevent legal violations and respond effectively when problems arise.", "children": [{"id": "8cc2d279-59a0-455a-8e86-1503a7085043", "type": "subtopic", "title": "Regulatory agencies and enforcement", "children": [{"id": "7cd9c851-45ee-403b-9080-471f41de5988", "type": "concept", "title": "EEOC"}, {"id": "6c3a6273-245b-477a-89b5-326caffec869", "type": "concept", "title": "DOL"}, {"id": "92e38598-413a-4073-b0d8-ac7e85d45c5f", "type": "concept", "title": "OSHA"}, {"id": "0ab37125-ab9b-44f6-a2ab-9c4f502592fd", "type": "concept", "title": "NLRB"}, {"id": "d7a71216-2f62-4e61-9e1a-d12a6d01d102", "type": "concept", "title": "FTC"}, {"id": "5cd374a1-d167-4c51-8577-4ba13a46e008", "type": "concept", "title": "State agencies"}], "description": "Students learn how agencies create rules, investigate, and enforce compliance."}, {"id": "9312a3d2-6579-4315-b96e-01a54976a89f", "type": "subtopic", "title": "Compliance program design", "children": [{"id": "1f884fdc-bedf-4cf4-b569-f4ae048bb7a4", "type": "concept", "title": "Codes of conduct"}, {"id": "95f45fb0-48a3-4570-8994-a031c1110e8c", "type": "concept", "title": "Policies"}, {"id": "801802e7-cf33-4cce-8b7e-b8d75fc660e6", "type": "concept", "title": "Training"}, {"id": "5c8557d5-f3b1-4dd4-8483-c2fd19a8484e", "type": "concept", "title": "Hotlines"}, {"id": "4571b05d-22f7-4461-a85a-63f53c734921", "type": "concept", "title": "Internal investigations"}, {"id": "494171a5-34d7-445b-8f5b-7e103851c94d", "type": "concept", "title": "Corrective action"}], "description": "This subtopic shows how organizations translate law into operating routines."}, {"id": "71513c62-ec7f-45c9-a679-7291790ab9f9", "type": "subtopic", "title": "Risk assessment and documentation", "children": [{"id": "a24b90ef-1652-4e2e-9521-36a4a7498717", "type": "concept", "title": "Risk registers"}, {"id": "13423833-eff0-42f7-a1ad-242d1d0195b0", "type": "concept", "title": "Audit trails"}, {"id": "35f55933-a2a1-4d9f-ad36-71d0f98724d5", "type": "concept", "title": "Retention schedules"}, {"id": "ecbafaf1-b5e4-4bfe-8b84-e89d19498f56", "type": "concept", "title": "Privilege awareness"}, {"id": "29d8dc21-d41b-47b6-b26e-9595a4940061", "type": "concept", "title": "Incident response"}, {"id": "db7abcf9-fa8c-43bb-88f6-97c78c39f1a2", "type": "concept", "title": "Escalation protocols"}], "description": "Students learn to identify high-risk processes and build records that support responsible decisions."}]}, {"id": "641b0540-6a90-46ba-acd0-df6a1239dc54", "type": "topic", "title": "Intellectual Property, Trade Secrets, and Employee Mobility", "description": "HR professionals routinely handle confidential information, employee inventions, restrictive covenants, onboarding, and exits. This topic teaches how intellectual property law intersects with talent management.", "children": [{"id": "ebc4109b-eb66-4c9b-ab79-523c297a2897", "type": "subtopic", "title": "IP fundamentals", "children": [{"id": "0492c418-5b63-4866-9e88-85a5c5a37862", "type": "concept", "title": "Copyright"}, {"id": "430d49aa-d39d-4b2c-9758-1daf63d7e23d", "type": "concept", "title": "Trademark"}, {"id": "3ccd7af3-322e-47aa-99fb-7f1c5aabd151", "type": "concept", "title": "Patent"}, {"id": "fc5bc14b-7b31-4f54-a1d1-0ead6b7cfcc3", "type": "concept", "title": "Trade secrets"}, {"id": "bb1d9d70-1236-44be-8edb-ce97a4753955", "type": "concept", "title": "Licensing"}], "description": "Students learn the major forms of legal protection for business knowledge and creative work."}, {"id": "17054175-6b86-4192-882a-b19baae92803", "type": "subtopic", "title": "Employee-created work and ownership", "children": [{"id": "83aa1883-a7c8-4117-bed8-2736e89c4dea", "type": "concept", "title": "Work made for hire"}, {"id": "e36d65a5-a789-429a-9de4-5cef314bf8ee", "type": "concept", "title": "Invention assignment"}, {"id": "c3ad7c6a-241b-4a58-8bf8-488d641b7893", "type": "concept", "title": "Consultant agreements"}, {"id": "915c5fa0-9c0c-478a-8804-67cfdcc2e072", "type": "concept", "title": "Moral rights basics"}, {"id": "4389e359-6b4e-433b-8727-78139b0b9a92", "type": "concept", "title": "Open-source issues"}], "description": "This subtopic explains who owns work created in employment or contractor relationships."}, {"id": "37d91b81-3aae-4e06-b486-683a498656fa", "type": "subtopic", "title": "Restrictive covenants and mobility", "children": [{"id": "5d3af5b3-a611-4c82-b115-fb21f5fc1b3d", "type": "concept", "title": "Noncompetes"}, {"id": "8a1d0576-c102-4d97-8a37-389fdc8a1aa2", "type": "concept", "title": "Nonsolicitation"}, {"id": "2dad2325-efa2-4157-a249-cd99b5f95357", "type": "concept", "title": "Nondisclosure agreements"}, {"id": "86afef90-7bc3-4c32-94b8-afe46edbb75a", "type": "concept", "title": "Garden leave"}, {"id": "c0f1864b-3d84-46b1-95c2-4d222d3776d0", "type": "concept", "title": "State-law variation"}, {"id": "3dbb89dd-6c4a-41a3-801f-50a43ab41ecd", "type": "concept", "title": "Trade secret misappropriation"}], "description": "Students learn the legal and policy debates around protecting knowledge without unlawfully restraining workers."}]}, {"id": "af9a0b02-f086-4112-87cb-a59020ec7e38", "type": "topic", "title": "Privacy, Data Protection, Cybersecurity, and HR Records", "description": "Business law now requires careful handling of personal data. HR students learn privacy principles for employee records, monitoring, background checks, health information, people analytics, and cybersecurity incidents.", "children": [{"id": "8f6a90ab-64fe-49ca-87a5-9822b78cebaa", "type": "subtopic", "title": "Employee privacy and monitoring", "children": [{"id": "5505a54d-8934-43bb-807d-7490bed9016d", "type": "concept", "title": "Notice and consent"}, {"id": "23fd9637-f3e3-4542-8cf8-ce681222cd4b", "type": "concept", "title": "Electronic monitoring"}, {"id": "002cc554-df72-4f78-be7f-3fb14556140c", "type": "concept", "title": "Biometric data"}, {"id": "b0c196c2-43a7-4f23-a852-6bc7315f107c", "type": "concept", "title": "Location tracking"}, {"id": "baacb673-f912-401b-b307-e26aae0e4bb6", "type": "concept", "title": "Bring-your-own-device policies"}], "description": "Students learn how privacy expectations change across email, devices, biometrics, surveillance, and remote work."}, {"id": "ef372665-e6ca-474c-82db-bc8f53d0b698", "type": "subtopic", "title": "HR data and records", "children": [{"id": "0771c449-f79d-4a5a-9c82-e409670074f8", "type": "concept", "title": "Personnel files"}, {"id": "112e9245-c953-4b85-bb7c-11b031104284", "type": "concept", "title": "Medical records"}, {"id": "e9d2811c-9bf3-462e-b177-6aed2490a6dd", "type": "concept", "title": "I-9 records"}, {"id": "9ce8cc2f-8ddf-4433-84d8-e8f060535720", "type": "concept", "title": "Background checks"}, {"id": "4974d11a-d698-490d-bab1-3f20cecf1f2e", "type": "concept", "title": "FCRA"}, {"id": "a5386df5-b2fd-4d38-9ffd-784ae3fbaaf1", "type": "concept", "title": "Data minimization"}], "description": "This subtopic covers lawful collection, retention, access, and disposal of sensitive workforce information."}, {"id": "ab90ed92-cdec-4dfb-a8e0-a74aeaf7d360", "type": "subtopic", "title": "Cybersecurity and breach response", "children": [{"id": "3ac5cbf7-ce5c-487c-a049-78da7b976120", "type": "concept", "title": "Access controls"}, {"id": "56851665-e4d1-43df-a9e2-06813a9c2d1c", "type": "concept", "title": "Phishing"}, {"id": "9c963c94-a2ec-4219-8dd5-6757af1b9a60", "type": "concept", "title": "Vendor risk"}, {"id": "4539fdd9-90fe-42b9-b2ec-e2e992e121a8", "type": "concept", "title": "Incident response"}, {"id": "91efe1b7-aff4-4034-9b11-a04986e1b43b", "type": "concept", "title": "Breach notification"}, {"id": "e8d16024-daa3-4264-8add-4c4112bce65b", "type": "concept", "title": "Training and audits"}], "description": "Students connect data protection to operational risk and legal duties after an incident."}]}, {"id": "3969cedc-94f8-4100-b118-c3a7267159e8", "type": "topic", "title": "Ethics, Corporate Social Responsibility, and Professional Judgment", "description": "The best HR legal decisions are not merely technically compliant. Students learn how ethics, stakeholder analysis, fairness, culture, and professional responsibility shape choices where the law gives discretion.", "children": [{"id": "2bf99fb8-1ff7-4cdf-a9da-5ab706a96d30", "type": "subtopic", "title": "Ethical decision frameworks", "children": [{"id": "9a4bf5f4-49ed-4526-80d4-3b48424552e9", "type": "concept", "title": "Stakeholder analysis"}, {"id": "eb2e6648-c32e-4c05-8ce4-cfde96378b26", "type": "concept", "title": "Rights and duties"}, {"id": "2124c882-118a-4990-a354-0f13dc3cd97d", "type": "concept", "title": "Consequences"}, {"id": "0e698005-b5de-469f-b7aa-4b81e87d16bc", "type": "concept", "title": "Justice and fairness"}, {"id": "c135e662-4578-4717-b8a8-d3bb6cc82060", "type": "concept", "title": "Professional integrity"}], "description": "Students learn structured ways to reason through ambiguous business and workplace problems."}, {"id": "61b35fde-892f-488e-8eb6-65b1dad38272", "type": "subtopic", "title": "Corporate social responsibility and ESG", "children": [{"id": "dfac9d04-f2c4-43cb-8a7d-9cfc50c563ae", "type": "concept", "title": "Human rights"}, {"id": "4e955e03-f7df-47b8-87cc-82451eb637fc", "type": "concept", "title": "Supply chains"}, {"id": "52e58a70-18dd-4004-a4ae-fc805db27570", "type": "concept", "title": "Pay equity"}, {"id": "009e89f4-3766-40bf-98b6-c65defcdc325", "type": "concept", "title": "Board oversight"}, {"id": "7d8f16cb-18e5-4ecb-8a59-437b715f736c", "type": "concept", "title": "ESG disclosure"}, {"id": "59d16999-a204-4c52-a1b7-f727a490bdcc", "type": "concept", "title": "Greenwashing risk"}], "description": "This subtopic links legal compliance to broader commitments around workers, communities, sustainability, and governance."}, {"id": "431b25fc-85ae-4a17-8752-f41d59d7a1d2", "type": "subtopic", "title": "HR professional responsibility", "children": [{"id": "65a63b6a-3d33-46ca-8646-698f4ea05eab", "type": "concept", "title": "Confidentiality"}, {"id": "12272363-35d8-4623-afdc-5b26eee71b00", "type": "concept", "title": "Conflicts of interest"}, {"id": "97665199-f774-449b-8c2c-39d98954c3ae", "type": "concept", "title": "Candor with counsel"}, {"id": "fdce2294-c72f-44a5-be5d-0923357f84bd", "type": "concept", "title": "Employee advocacy"}, {"id": "bca7afd6-205d-4922-abe2-eb35f05c8bf7", "type": "concept", "title": "Retaliation prevention"}, {"id": "e0427fe9-8d43-43bc-bf97-ca27a8cc84f9", "type": "concept", "title": "Ethical escalation"}], "description": "Students learn how HR maintains trust while serving employees, managers, and the organization."}]}, {"id": "f7502f69-95dd-4bc2-b490-7964de96832c", "type": "topic", "title": "Legal Case Analysis and HR Issue Spotting Capstone", "description": "The capstone trains students to read cases, brief legal issues, analyze messy facts, and communicate practical recommendations. The emphasis is not memorizing rules, but becoming the HR professional who can see the issue early and frame it responsibly.", "children": [{"id": "a4c76a70-a943-4803-812b-1e92487ff4c4", "type": "subtopic", "title": "Case briefing", "children": [{"id": "4b92d163-09e6-4280-bd02-4cefa87c4e87", "type": "concept", "title": "Facts"}, {"id": "90b6171a-b33a-4594-8cc4-2e0bc4490a48", "type": "concept", "title": "Procedural posture"}, {"id": "3b598be7-599f-4a46-89b7-0ce37f9bedfb", "type": "concept", "title": "Issue"}, {"id": "d0be2804-1f65-447b-aa01-0c7a7bc73ee6", "type": "concept", "title": "Holding"}, {"id": "806ce303-90a3-44f0-b19f-29eb397e201a", "type": "concept", "title": "Reasoning"}, {"id": "b59db048-d0d2-4d3a-bebf-ee6efe3ddd38", "type": "concept", "title": "Dissent"}], "description": "Students practice extracting rules and reasoning from judicial opinions and agency decisions."}, {"id": "d6d587f8-b61d-4153-89fb-2c100f2f5992", "type": "subtopic", "title": "Scenario-based issue spotting", "children": [{"id": "ae5be9bc-299e-4c41-8362-24e505c69001", "type": "concept", "title": "Hiring scenarios"}, {"id": "4c674bc0-e306-4df0-99c2-6f945c5bcccb", "type": "concept", "title": "Termination scenarios"}, {"id": "3dd80c12-3ebf-4620-8999-85e73c1913c3", "type": "concept", "title": "Harassment investigations"}, {"id": "51de2d53-f75f-4d98-b117-5b1c89709962", "type": "concept", "title": "Leave and accommodation"}, {"id": "a782a819-61e2-4c67-a3cb-8d15d2a82363", "type": "concept", "title": "Data incidents"}, {"id": "8aea648c-53c2-4cb1-93e7-74ebc4be5ef5", "type": "concept", "title": "Union activity"}], "description": "This subtopic develops the habit of identifying legal, ethical, operational, and reputational risks in one fact pattern."}, {"id": "504011bf-942c-433c-8e3c-ed757ec4d805", "type": "subtopic", "title": "Professional legal communication", "children": [{"id": "f99a808c-cb96-4b44-aa77-e9dc65970e1c", "type": "concept", "title": "Executive summary"}, {"id": "81d86718-b8cc-4eff-a6dc-87fc52da7a08", "type": "concept", "title": "Risk rating"}, {"id": "93e5843c-7978-4bda-ab82-71cc1e4ca2eb", "type": "concept", "title": "Open facts"}, {"id": "c95f5206-71f5-47a6-b5ae-a29dbd9c8ce1", "type": "concept", "title": "Options and tradeoffs"}, {"id": "84b3a68b-945b-4ec3-a2a0-4f9adced4f88", "type": "concept", "title": "Recommended next steps"}, {"id": "1a8993f1-35fb-41a9-8b12-ca1dae9207dc", "type": "concept", "title": "Questions for counsel"}], "description": "Students learn to write concise, non-lawyer legal risk analyses for managers and counsel."}]}], "dbBacked": true}$blawjson$::jsonb,
