update public.learning_paths
set
  title = 'Business Law',
  goal = 'Business Law',
  summary = 'This course introduces the legal environment of business through the lens of human resources. Students learn the foundations of courts, contracts, agency, torts, business organizations, employment law, labor law, regulation, intellectual property, privacy, ethics, and legal case analysis. The emphasis is practical: spotting legal issues early, documenting decisions responsibly, knowing when to involve counsel, and communicating risk in a professional HR voice.',
  data = $blawjson${"slug": "business-law", "title": "Business Law", "description": "This course introduces the legal environment of business through the lens of human resources. Students learn the foundations of courts, contracts, agency, torts, business organizations, employment law, labor law, regulation, intellectual property, privacy, ethics, and legal case analysis. The emphasis is practical: spotting legal issues early, documenting decisions responsibly, knowing when to involve counsel, and communicating risk in a professional HR voice.", "topics": [{"id": "251a65d6-8489-43c8-bf63-4ef7c49897a7", "type": "topic", "title": "Legal Systems, Courts, and HR Legal Reasoning", "description": "Students learn how law is made, interpreted, and applied to workplace and business decisions. The goal is legal literacy: recognizing risk, organizing facts, communicating with counsel, and understanding how courts and agencies resolve disputes.", "children": [{"id": "fb8152d4-414d-4ccf-ac30-940da6b2a6ee", "type": "subtopic", "title": "Sources of law", "children": [{"id": "8d67d5b8-9209-4bdc-b554-ee47f52ecdad", "type": "concept", "title": "Constitutions"}, {"id": "4c0b6ca7-7e25-4162-8f5c-053933ad454a", "type": "concept", "title": "Statutes"}, {"id": "f8296bb6-960b-4653-9a3e-db785bd6cf81", "type": "concept", "title": "Regulations"}, {"id": "8ed6a328-b05d-4dfb-9269-aa113d654806", "type": "concept", "title": "Common law"}, {"id": "02cdfa46-4124-4750-b45c-cd67337a75c1", "type": "concept", "title": "Administrative guidance"}], "description": "This subtopic gives students the map of legal authority that governs business and HR decisions."}, {"id": "81991604-68b4-464c-aab6-f312a555edee", "type": "subtopic", "title": "Court systems and jurisdiction", "children": [{"id": "a745b36f-8986-481f-978d-9a2e438a5af9", "type": "concept", "title": "Federal versus state courts"}, {"id": "5b4fa759-2748-40c2-9c3b-018a9358faae", "type": "concept", "title": "Trial and appellate courts"}, {"id": "d3ffb13e-ec8b-4591-97db-7f1ddd31bd6f", "type": "concept", "title": "Jurisdiction"}, {"id": "99af2df0-0fbb-476e-be6c-d3f8f597a409", "type": "concept", "title": "Venue"}, {"id": "40cb3d63-b01a-48a3-a753-326114d2aa11", "type": "concept", "title": "Civil versus criminal matters"}], "description": "Students learn where disputes are heard and why forum, procedure, and remedies matter."}, {"id": "30db72c2-99d6-49fb-a5d1-3cf0d358dfa9", "type": "subtopic", "title": "Legal reasoning for HR professionals", "children": [{"id": "24b9f4e0-e2d4-4944-a128-011889ea1cec", "type": "concept", "title": "Issue-rule-application-conclusion"}, {"id": "8ca1995a-a634-46bc-a116-df9048b086aa", "type": "concept", "title": "Material facts"}, {"id": "39b0e95c-8f7c-429a-a205-edd2817dbbc1", "type": "concept", "title": "Precedent"}, {"id": "e780e771-e89e-4f98-af91-f28fba90538e", "type": "concept", "title": "Risk escalation"}, {"id": "6b60da88-a79a-4db9-9828-3687c0f22c0d", "type": "concept", "title": "Documentation habits"}], "description": "The point is to move from vague concern to structured issue spotting and defensible recommendations."}]}, {"id": "b77d2e22-1f42-454e-91c5-6e49827d5152", "type": "topic", "title": "Contracts: Formation, Performance, Breach, and Remedies", "description": "Contracts are the operating system of business relationships. HR students learn how promises become enforceable, how agreements are interpreted, and how contract design affects employees, vendors, consultants, and executives.", "children": [{"id": "1fd2f556-c864-47f6-ad66-572c5b0af5c6", "type": "subtopic", "title": "Contract formation", "children": [{"id": "82ace9f6-1352-4c99-8deb-b017566fe947", "type": "concept", "title": "Offer"}, {"id": "721435b9-9855-4832-a6f5-cdc7c4bfcdf5", "type": "concept", "title": "Acceptance"}, {"id": "9c86c763-c364-4a3c-bafc-65fecbfb5459", "type": "concept", "title": "Consideration"}, {"id": "d87d72fa-580f-41e4-95af-708f9a140657", "type": "concept", "title": "Capacity"}, {"id": "448d718a-a134-464a-a3a1-1090c46cfa7e", "type": "concept", "title": "Legality"}, {"id": "bc17c314-4c0d-4863-9777-8583fb910795", "type": "concept", "title": "Mutual assent"}], "description": "Students learn the elements that turn negotiation into an enforceable obligation."}, {"id": "bf66aabd-bbda-45cf-a180-eb704eb15212", "type": "subtopic", "title": "Performance and breach", "children": [{"id": "14899b17-ea22-48c8-bfd1-6d3efaddf821", "type": "concept", "title": "Conditions"}, {"id": "9e53e8f5-d861-491c-9f96-60a0be3b1581", "type": "concept", "title": "Material breach"}, {"id": "a35128f1-7f80-4676-b2f9-992a06ff7ea2", "type": "concept", "title": "Substantial performance"}, {"id": "95bc5ad2-44ab-4698-b0d1-60afb92ce699", "type": "concept", "title": "Impossibility"}, {"id": "e8b96ff9-54cf-4772-ab82-1ed8eb2e6afc", "type": "concept", "title": "Good faith"}, {"id": "5b78bc9c-ad97-41dd-b658-c9d1a9d8bc27", "type": "concept", "title": "Mitigation"}], "description": "This subtopic shows how obligations are fulfilled, excused, or violated."}, {"id": "bd28d464-2389-4c1a-b435-1f8a44cc2478", "type": "subtopic", "title": "Remedies and drafting controls", "children": [{"id": "35a1f98d-794e-4670-ad08-04ec1f317cfe", "type": "concept", "title": "Expectation damages"}, {"id": "f09e51c3-adbe-4613-a261-63bd4f62a2b6", "type": "concept", "title": "Specific performance"}, {"id": "9ddaf584-97fd-4c90-a8a6-f25bbfdf4259", "type": "concept", "title": "Liquidated damages"}, {"id": "bc988ceb-7a65-4bb8-8900-54ce18d58c87", "type": "concept", "title": "Limitation of liability"}, {"id": "937cc14b-c0c4-42d9-87f6-0c7a503a00ee", "type": "concept", "title": "Indemnification"}, {"id": "44792c41-b810-4f99-a68c-1d5b04ce0af8", "type": "concept", "title": "Dispute clauses"}], "description": "Students learn how contracts allocate risk before something goes wrong."}]}, {"id": "24b78a98-3160-48d4-907d-019176ebca93", "type": "topic", "title": "Agency Law and Authority in Organizations", "description": "Agency law explains how organizations act through people. For HR, it is essential for understanding hiring authority, supervisor conduct, apparent authority, fiduciary duties, and organizational liability.", "children": [{"id": "67b8c05d-7b9b-4831-9297-6355eb129594", "type": "subtopic", "title": "Creation of agency relationships", "children": [{"id": "44e2ad6a-7004-46ae-964b-6e7d03fa83b9", "type": "concept", "title": "Principal and agent"}, {"id": "de8066eb-320b-4f5f-b00f-090e68b4b6a0", "type": "concept", "title": "Actual authority"}, {"id": "49a6c8a0-2ba4-478f-8f40-e884d7a28927", "type": "concept", "title": "Apparent authority"}, {"id": "89c1f6c4-a560-4a6f-90a2-2a416fbcd1f4", "type": "concept", "title": "Ratification"}, {"id": "f4d172d4-3554-4a18-9554-f8360deba101", "type": "concept", "title": "Independent contractors"}], "description": "Students learn when one person legally acts on behalf of another person or entity."}, {"id": "10092986-e30f-478c-b1d2-9b238a3a715d", "type": "subtopic", "title": "Duties of agents and principals", "children": [{"id": "948fae21-b54a-4499-8f52-0a22e5f1882a", "type": "concept", "title": "Duty of loyalty"}, {"id": "346cd1a0-04c6-4df2-ad57-6d10c282c7de", "type": "concept", "title": "Duty of care"}, {"id": "33536ed1-b3c1-4811-a5fe-2fa0029596d2", "type": "concept", "title": "Conflicts of interest"}, {"id": "9f67f72a-31d0-4fdc-b4ae-136a9196d376", "type": "concept", "title": "Confidentiality"}, {"id": "d6699e88-2bd9-424e-abb1-aa0ac04d9770", "type": "concept", "title": "Indemnification"}], "description": "This subtopic explains loyalty, care, disclosure, and accountability within organizational roles."}, {"id": "39c7bc20-50b8-440b-89ba-b1249c4f59e1", "type": "subtopic", "title": "Employer liability for agents", "children": [{"id": "cb5c5d5b-42f9-45c0-a791-9d9ee844e9f1", "type": "concept", "title": "Respondeat superior"}, {"id": "850d8ce4-73f0-41b6-8a83-dd3c723bcf4e", "type": "concept", "title": "Scope of employment"}, {"id": "46f23d83-f275-446a-9243-726e9a288cf1", "type": "concept", "title": "Frolic and detour"}, {"id": "c8508307-47c0-44ea-9b93-d0e55a0520d9", "type": "concept", "title": "Negligent hiring"}, {"id": "d492a597-57ec-456c-8bfa-c557cb983bba", "type": "concept", "title": "Supervisor conduct"}], "description": "Students learn when organizations are responsible for employee or manager conduct."}]}, {"id": "38a2e06d-b431-4050-bbfe-d419cd1dca85", "type": "topic", "title": "Torts, Negligence, Product Liability, and Workplace Risk", "description": "Tort law teaches students how businesses become liable for harm outside contract. HR students connect tort concepts to workplace safety, defamation, negligent hiring, emotional distress, and risk prevention.", "children": [{"id": "69d38aef-2b62-4e27-85f9-6469fb5a239b", "type": "subtopic", "title": "Negligence and duty of care", "children": [{"id": "91b999a6-0199-41e8-80df-4a7839c7039d", "type": "concept", "title": "Duty"}, {"id": "5320bd9c-507c-4e29-968d-d9ff4ace9007", "type": "concept", "title": "Breach"}, {"id": "177ddaa7-501a-4bc0-8c8b-3fd8489a70a0", "type": "concept", "title": "Causation"}, {"id": "2158c689-ce62-4b1f-abcf-31ac7aa60899", "type": "concept", "title": "Damages"}, {"id": "cb6f312c-9a3e-4a76-857c-b9e8e211e878", "type": "concept", "title": "Foreseeability"}, {"id": "891febd6-230d-43cc-9d4c-4a18e3133343", "type": "concept", "title": "Comparative fault"}], "description": "Students learn the basic framework for civil liability based on unreasonable conduct."}, {"id": "c5046b9d-0d7f-4572-a657-82f7d24e9804", "type": "subtopic", "title": "Intentional and business torts", "children": [{"id": "67acd8f8-ea1f-49ef-9e3b-34a184a3a4fd", "type": "concept", "title": "Defamation"}, {"id": "db1c3140-15f2-4c12-bbce-7ddf24518a5e", "type": "concept", "title": "Fraud"}, {"id": "5ed421fb-9c1c-4fe5-aa63-41eaa0fd45e5", "type": "concept", "title": "Interference with contract"}, {"id": "01ef5517-6d83-41ee-a413-300fd1715375", "type": "concept", "title": "Intentional infliction of emotional distress"}, {"id": "632398e2-14cf-45de-a909-0e92d4aa54c9", "type": "concept", "title": "Invasion of privacy"}], "description": "This subtopic helps students recognize workplace and commercial conduct that creates civil exposure."}, {"id": "bce662c1-880e-48a9-addb-c4dfe5972c44", "type": "subtopic", "title": "Workplace tort risk", "children": [{"id": "b289df7a-783c-4d18-8377-484f7186dd0b", "type": "concept", "title": "Negligent hiring"}, {"id": "e97f9ea1-0123-4d51-8637-775f480972b5", "type": "concept", "title": "Negligent retention"}, {"id": "8086306b-896f-4713-9d88-61eabfec2013", "type": "concept", "title": "Workplace violence"}, {"id": "c5a49801-5f6c-4938-b29b-e529df371269", "type": "concept", "title": "Reference checks"}, {"id": "26505f25-efb0-4f0d-8428-e087d552978d", "type": "concept", "title": "Investigation notes"}, {"id": "1bab4afd-3d96-4037-b1aa-c088787946d8", "type": "concept", "title": "Insurance and risk transfer"}], "description": "Students connect legal doctrine to hiring, supervision, references, investigations, and safety."}]}, {"id": "466618d0-150e-47e3-b01f-ab4f213af8da", "type": "topic", "title": "Business Organizations, Governance, and Fiduciary Duties", "description": "Students learn the legal forms businesses use and how governance structures allocate authority, responsibility, liability, and accountability. HR professionals need this foundation when advising leaders and operating in complex organizations.", "children": [{"id": "64bd624e-3965-472d-88d3-aeb65c68b483", "type": "subtopic", "title": "Entity forms and liability", "children": [{"id": "a34584d9-aee5-4eb7-af10-7eb37e963ca5", "type": "concept", "title": "Sole proprietorships"}, {"id": "5f4e6fd9-54c5-4f63-97a3-911aa746c702", "type": "concept", "title": "Partnerships"}, {"id": "b09953af-d8ad-455f-bfa1-cbbe77ba8083", "type": "concept", "title": "LLCs"}, {"id": "5a8b08b3-e791-44cf-a7ca-494a9d55779c", "type": "concept", "title": "Corporations"}, {"id": "cc26c144-5647-43a4-9c3c-14da2d6683df", "type": "concept", "title": "Limited liability"}, {"id": "82d1b1bb-aedb-46bb-adca-aac2fb25ffb9", "type": "concept", "title": "Piercing the veil"}], "description": "This subtopic compares the main legal structures used by employers and clients."}, {"id": "7aad3467-6b63-4603-9eba-ad8b91f7b925", "type": "subtopic", "title": "Corporate governance", "children": [{"id": "bc50ab69-6666-436b-9b09-7e4caaf6a17d", "type": "concept", "title": "Board authority"}, {"id": "8aef7399-3a90-4725-bb2c-623d677ad4bd", "type": "concept", "title": "Officer roles"}, {"id": "a861469c-5ea1-46c2-ad60-22c53d2089f9", "type": "concept", "title": "Shareholder rights"}, {"id": "d18bc76c-9b1c-4ac4-b543-23d09ebeb93b", "type": "concept", "title": "Corporate records"}, {"id": "e3de1d37-eccc-41b9-9cec-46d6f8885bf7", "type": "concept", "title": "Internal controls"}], "description": "Students learn how directors, officers, shareholders, and managers make and supervise decisions."}, {"id": "b760ebc6-b0a2-4b98-9db2-8a3a59410a60", "type": "subtopic", "title": "Fiduciary duties and ethical governance", "children": [{"id": "43b18b85-40ae-45ab-9054-ace7a8c0ea64", "type": "concept", "title": "Duty of care"}, {"id": "11b983b4-293d-460e-b7f2-5e93025bdf0b", "type": "concept", "title": "Duty of loyalty"}, {"id": "75ae95b7-22ce-4a70-85c6-95a11f8449e2", "type": "concept", "title": "Business judgment rule"}, {"id": "69e33c85-b471-4731-b86d-9fe887159aa1", "type": "concept", "title": "Conflicts of interest"}, {"id": "0cac8ee2-0b7a-4c04-91ba-7b36aae3b3a6", "type": "concept", "title": "Whistleblower channels"}, {"id": "d8de88f0-c75e-4c65-ba3f-e1f04c9f5dc5", "type": "concept", "title": "Board reporting"}], "description": "The goal is to understand legal duties of loyalty and care in business leadership."}]}, {"id": "173a5f02-9306-4aa5-bda3-e33c7ccd23c0", "type": "topic", "title": "Employment Law Foundations for HR", "description": "For a Human Resources degree, employment law needs real depth. Students learn the legal baseline for hiring, classification, pay, leave, accommodation, discipline, discharge, and employee relations.", "children": [{"id": "6535b660-5231-4e46-961d-bf4830f1985b", "type": "subtopic", "title": "Employment relationship and classification", "children": [{"id": "26da515a-28fd-4906-a6ef-fe74393500e7", "type": "concept", "title": "At-will employment"}, {"id": "1551fdf5-309b-483b-b29b-7ea9d8fc60a9", "type": "concept", "title": "Employee versus independent contractor"}, {"id": "441db0fb-de2f-45db-bf6e-f1b090c43f92", "type": "concept", "title": "Exempt versus nonexempt"}, {"id": "92a531a4-bae1-430e-a9ea-e981bb54cf6a", "type": "concept", "title": "Joint employment"}, {"id": "58cd9625-6def-4465-996e-5c16a52c5fa3", "type": "concept", "title": "Interns and trainees"}], "description": "Students learn how legal status affects rights, pay, benefits, taxes, and liability."}, {"id": "165a638a-c53f-4ed3-8140-f56e0c76b3f7", "type": "subtopic", "title": "Equal employment opportunity", "children": [{"id": "fad6e39b-c24b-4b5e-a4ae-9fb4cafe5a22", "type": "concept", "title": "Title VII"}, {"id": "6371df50-d00b-4081-b5ca-9ce9d1cf89c8", "type": "concept", "title": "ADA"}, {"id": "e29f127d-2169-4b17-bb28-413847cc79ed", "type": "concept", "title": "ADEA"}, {"id": "968d2cbf-8ab7-4d83-9aa8-8cb7a52e29d9", "type": "concept", "title": "Pregnancy discrimination"}, {"id": "98bb1166-0161-4bf3-aea3-b5b36e7ed76d", "type": "concept", "title": "Harassment"}, {"id": "68605aa7-20da-401e-b74e-0d607d3ee332", "type": "concept", "title": "Retaliation"}], "description": "This subtopic introduces the legal framework for fair treatment across the employment lifecycle."}, {"id": "b20e7637-c194-43b4-9e80-89b21873dbda", "type": "subtopic", "title": "Workplace standards and separation", "children": [{"id": "ed490cfc-741f-429d-b14c-54dfe3476015", "type": "concept", "title": "FLSA"}, {"id": "c0025a2d-17d5-4764-ab35-e0c0bb61597f", "type": "concept", "title": "FMLA"}, {"id": "79af7856-b0b8-4de0-998c-025c3810e322", "type": "concept", "title": "OSHA"}, {"id": "7ae901eb-8285-42e8-bb56-0847e687a074", "type": "concept", "title": "Wrongful discharge"}, {"id": "9ae335ad-1aa7-437d-8607-b979d80ca69c", "type": "concept", "title": "Progressive discipline"}, {"id": "15a6f32f-1d7d-4b0e-bd22-fc42d06fd316", "type": "concept", "title": "Severance and releases"}], "description": "Students learn core rules that govern pay, leave, safety, discipline, and termination."}]}, {"id": "236540f1-056a-4e9c-9124-922934c0e899", "type": "topic", "title": "Labor Law, Employee Voice, and Collective Activity", "description": "A world-class HR business law course should not stop at individual employment rights. Students learn how labor law protects collective activity, union organizing, bargaining, and protected employee voice.", "children": [{"id": "88a2d8a3-524f-496b-85e2-1fbb7f0c238b", "type": "subtopic", "title": "National Labor Relations Act basics", "children": [{"id": "834c7930-7271-4061-9efd-b0fb62ac7d72", "type": "concept", "title": "Protected concerted activity"}, {"id": "43c4e0b0-8e42-49b2-9730-c53f3d30c5e2", "type": "concept", "title": "Section 7 rights"}, {"id": "d5998190-9457-4cb2-b9f0-879887fe92cb", "type": "concept", "title": "Unfair labor practices"}, {"id": "1714ae14-dff4-4bee-9824-45e257b7c607", "type": "concept", "title": "NLRB process"}, {"id": "9063859a-e0a1-4044-81fa-773f8a8f077c", "type": "concept", "title": "Manager do's and don'ts"}], "description": "Students learn the federal framework for private-sector union and nonunion employee rights."}, {"id": "d3a35bfa-f9c3-495d-9d5a-73a1b528aea8", "type": "subtopic", "title": "Organizing and bargaining", "children": [{"id": "42c32db2-208d-463f-a0b5-b6af7fd8cc03", "type": "concept", "title": "Authorization cards"}, {"id": "aa238a64-a36a-4592-adb4-0ba22b966b78", "type": "concept", "title": "Representation elections"}, {"id": "01d19e75-4070-4a9f-9859-4fc5cad9b08b", "type": "concept", "title": "Duty to bargain"}, {"id": "be5e9ef5-f7f4-413f-a366-ae1873bb6aff", "type": "concept", "title": "Management rights"}, {"id": "218cf6e0-9beb-4ca1-b6eb-93b879332bc1", "type": "concept", "title": "Collective bargaining agreements"}], "description": "This subtopic introduces how representation, negotiation, and contracts shape workplace governance."}, {"id": "64a4ac7e-a5a7-4f0b-85e3-622ff3486bea", "type": "subtopic", "title": "Employee voice beyond unions", "children": [{"id": "44fd4f82-2cc0-4eca-a1d2-59f2ac7c8888", "type": "concept", "title": "No-retaliation rules"}, {"id": "61904ba5-50ea-45ba-afde-32d71e2334c2", "type": "concept", "title": "Handbook policies"}, {"id": "63a7c271-3abc-4e30-8c61-bf66390fbd7d", "type": "concept", "title": "Confidentiality limits"}, {"id": "a64437ed-e013-4a93-bf2a-9ab95c12e33b", "type": "concept", "title": "Whistleblowing"}, {"id": "cad1f33c-25d0-4d04-9fcb-6e7b123c4aae", "type": "concept", "title": "Speak-up culture"}], "description": "Students understand legal risk in policies that affect complaints, social media, and workplace organizing."}]}, {"id": "84a4f2df-1543-41e3-821b-2684acab0707", "type": "topic", "title": "Regulation, Compliance Systems, and Risk Management", "description": "Regulation is not only a list of rules; it is a management system. Students learn how businesses build controls, training, audits, documentation, and reporting pathways that prevent legal violations and respond effectively when problems arise.", "children": [{"id": "8cc2d279-59a0-455a-8e86-1503a7085043", "type": "subtopic", "title": "Regulatory agencies and enforcement", "children": [{"id": "7cd9c851-45ee-403b-9080-471f41de5988", "type": "concept", "title": "EEOC"}, {"id": "6c3a6273-245b-477a-89b5-326caffec869", "type": "concept", "title": "DOL"}, {"id": "92e38598-413a-4073-b0d8-ac7e85d45c5f", "type": "concept", "title": "OSHA"}, {"id": "0ab37125-ab9b-44f6-a2ab-9c4f502592fd", "type": "concept", "title": "NLRB"}, {"id": "d7a71216-2f62-4e61-9e1a-d12a6d01d102", "type": "concept", "title": "FTC"}, {"id": "5cd374a1-d167-4c5